location.text:
export function threadPresentation(thread: { state: Thread["state"] | "IN_PROGRESS" }): {
  label: string;
  tone: string;
} {

  switch (thread.state) {
    case "IN_PROGRESS":
      return { label: "In progress", tone: "active" };
    case "ACTIVE":
      return { label: "Open", tone: "active" };
    case "FROZEN":
      return { label: "Paused", tone: "frozen" };
    case "COMPLETED":
      return { label: "Completed", tone: "completed" };
    default:
      throw new Error(`Unknown thread state: ${String(thread.state)}`);
  }
}

related.text:
export const threadState = (thread: Pick<Thread, "state">, atWork = false): PillState => {
  switch (thread.state) {
    case "ACTIVE":
      return atWork ? { label: "In progress", role: "warning" } : { label: "Open", role: "accent" };
    case "FROZEN":
      return { label: "Paused", role: "waiting" };
    case "COMPLETED":
      return { label: "Completed", role: "success" };
    default:
      throw new Error(`Unknown thread state: ${String(thread.state)}`);
  }
};
